173	  gainingCount: number,
174	  slippingCount: number,
175	  framing?: { gaining: string; mixed: string; slipping: string }
176	): 'gaining' | 'mixed' | 'slipping' | null {
177	  if (!framing) return null;
178	  const decisive = gainingCount + slippingCount;
179	  if (decisive === 0) return 'mixed';
180	  const ratio = gainingCount / decisive;
181	  if (ratio >= 0.66) return 'gaining';
182	  if (ratio <= 0.34) return 'slipping';
183	  return 'mixed';
184	}
