187	// query string so the page can recompute the map on load. Encoded as a single
188	// `a` param, `qid-index` pairs joined by `.` (ids never contain those chars).
189	export function buildMapMoveQuery(
190	  quiz: QuizData,
191	  responses: QuizResponses
192	): URLSearchParams {
193	  const params = new URLSearchParams();
194	  const pairs: string[] = [];
195	  for (const question of quiz.questions) {
196	    const optionIndex = responses[question.id];
197	    if (optionIndex === undefined) continue;
198	    pairs.push(`${question.id}-${optionIndex}`);
199	  }
200	  params.set('a', pairs.join('.'));
201	  return params;
202	}
203	
204	export function parseMapMoveResponses(params: URLSearchParams): QuizResponses {
205	  const responses: QuizResponses = {};
206	  const raw = params.get('a');
207	  if (!raw) return responses;
208	  for (const pair of raw.split('.')) {
209	    const sep = pair.lastIndexOf('-');
210	    if (sep <= 0) continue;
211	    const id = pair.slice(0, sep);
212	    const index = parseInt(pair.slice(sep + 1), 10);
213	    if (id && Number.isInteger(index) && index >= 0) responses[id] = index;
214	  }
215	  return responses;
216	}
