1	---
2	export const prerender = false;
3	
4	import Layout from '@/layouts/base.astro';
5	import { findLevel, parseMapMoveResponses } from '@/lib/quiz-engine';
6	import MapMoveResults from '@/lib/quiz-engine/components/MapMoveResults.astro';
7	import { getEntry, render } from 'astro:content';
8	
9	const { slug } = Astro.params;
10	const entry = await getEntry('quizzes', slug!);
11	if (!entry) {
12	  return new Response(null, { status: 404, statusText: 'Not found' });
13	}
14	
15	const data = entry.data;
16	const params = Astro.url.searchParams;
17	const resultStyle = data.resultStyle ?? 'band';
18	
19	// --- map-move -------------------------------------------------------------
20	// The taker's answers ride in the `a` param; rebuild the map from them. If it's
21	// missing, send them back to the quiz rather than showing an empty result.
22	const mapMoveResponses =
23	  resultStyle === 'map-move' ? parseMapMoveResponses(params) : {};
24	if (resultStyle === 'map-move' && Object.keys(mapMoveResponses).length === 0) {
25	  return Astro.redirect(`/quiz/${entry.id}/`);
26	}
27	
28	// --- band -----------------------------------------------------------------
29	const totalRaw = params.get('total');
30	const maxRaw = params.get('max');
31	const level = params.get('level');
32	const total = totalRaw !== null ? parseInt(totalRaw, 10) : NaN;
33	const maxTotal = maxRaw !== null ? parseInt(maxRaw, 10) : NaN;
34	
35	if (
36	  resultStyle === 'band' &&
37	  (Number.isNaN(total) || Number.isNaN(maxTotal) || !level)
38	) {
39	  return Astro.redirect(`/quiz/${entry.id}/`);
40	}
41	
42	const overall =
43	  resultStyle === 'band' ? findLevel(total, data.overallLevels ?? []) : null;
44	const overallTitle = overall?.title ?? overall?.level ?? 'Your result';
45	
46	const { Content } = await render(entry);
47	---
48	
49	<Layout
50	  title={`${data.title} — Results`}
51	  description={data.description ?? data.title}
52	  includeCoursesCTA={false}
53	  noIndex={true}
54	>
55	  {
56	    resultStyle === 'map-move' ? (
57	      <div class="bg-quiz-page px-4 py-12 md:py-16">
58	        <MapMoveResults quiz={data} responses={mapMoveResponses} />
59	        <section class="mx-auto mt-10 max-w-170">
60	          <a
61	            href={`/quiz/${entry.id}/`}
62	            class="text-quiz-ink-muted text-[13px] hover:underline"
63	          >
64	            Take the quiz again
65	          </a>
66	        </section>
67	      </div>
68	    ) : (
69	      <div class="container mx-auto px-4 py-12 md:py-16">
70	        <section class="mx-auto mb-10 max-w-3xl text-center">
71	          <p class="mb-2 text-sm font-medium tracking-wide text-indigo-600 uppercase">
72	            Your result
73	          </p>
74	          <h1 class="mb-4 text-3xl font-bold text-gray-900 md:text-5xl">
75	            {overallTitle}
76	          </h1>
77	          <p class="mb-6 text-lg text-gray-700">
78	            You scored <strong>{total}</strong> out of{' '}
79	            <strong>{maxTotal}</strong>.
80	          </p>
81	          {data.resultsSubtitle ? (
82	            <p class="mx-auto max-w-2xl text-base/relaxed text-gray-700 md:text-lg/relaxed">
83	              {data.resultsSubtitle}
84	            </p>
85	          ) : null}
