// Simulates the candidate fix WITHOUT touching src/: make the sentence the
// opt-in for slipping answers too, exactly as it already is for context ones.
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const quiz: any = parse(raw.split('---')[1]);
const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');
const byId = Object.fromEntries(quiz.questions.map((q: any) => [q.id, q]));
const sentence = (qid: string, idx: number, field: string) =>
  byId[qid]?.options?.[idx]?.[field];

function pick(resp: Record<string, number>, priority: string[], field: string, exclude?: string) {
  for (const qid of priority) {
    const idx = resp[qid];
    if (idx === undefined || qid === exclude) continue;
    const bucket = byId[qid].options[idx]?.bucket;
    const has = !!sentence(qid, idx, field);
    // current rule: slipping always eligible | fixed rule: needs the sentence
    if ((bucket === 'slipping' || bucket === 'context') && has) return qid;
  }
  return null;
}

let both = 0, total = 0, noRedirect = 0;
const fallback = new Map<string, number>();
function walk(i: number, resp: Record<string, number>) {
  if (i === scored.length) {
    total++;
    const rec = pick(resp, quiz.mapMove.reclaimPriority, 'reclaimSentence');
    const red = pick(resp, quiz.mapMove.redirectPriority, 'redirectSentence', rec ?? undefined);
    if (red) { both++; fallback.set(red, (fallback.get(red) ?? 0) + 1); } else noRedirect++;
    return;
  }
  for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
}
walk(0, {});
console.log(`with the fix: ${both}/${total} get a redirect sentence, ${noRedirect} genuinely have no eligible target`);
console.log('which question supplies the redirect:', [...fallback.entries()].sort((a, b) => b[1] - a[1]));
