  },
};
const BOX_ORDER = ['tl', 'tr', 'bl', 'br'];
const boxOf = (p) => (p.human >= 0 ? 't' : 'b') + (p.scope < 0.5 ? 'l' : 'r');

// Verbatim from the quiz frontmatter.
const RECLAIM_PRIORITY = ['q3', 'q1', 'q2'];
const REDIRECT_PRIORITY = ['q2', 'q4', 'q7', 'q8', 'q5', 'q6'];
const RECLAIM_SENTENCE = {
  'q1:0': 'Reclaim the time. Running the events is the first place to lean on a tool or trim back. It’s expensive because it takes time away from the real value of facilitation and coaching.',
  'q3:0': 'Reclaim the time. That block of admin is the first thing to automate or simply stop doing. Use the time saved to coach the team or work on a systemic problem.',
