    { label: 'prep, on part-time hours', human: -0.8, scope: 0.12, attn: 0.7, bucket: 'context' },
  ],
};

// The four boxes, named for the WORK rather than the person, so this stays a
// map and never becomes an archetype label.
const BOXES = {
  tl: {
    name: 'the people work',
    line: 'one conversation at a time',
    empty: 'None of your time went here.',
  },
  tr: {
    name: 'the system work',
    line: 'problems that outlive a Sprint',
    empty: 'None of your time went here.',
  },
  bl: {
    name: 'your own overhead',
    line: 'prep, notes and write-ups you do alone',
    empty: 'Nothing you do on your own is work a tool is taking.',
  },
  br: {
    name: 'the coordination machine',
    line: 'keeping everyone lined up',
    empty: 'None of your time went here, which is rare.',
  },
};
const BOX_ORDER = ['tl', 'tr', 'bl', 'br'];
const boxOf = (p) => (p.human >= 0 ? 't' : 'b') + (p.scope < 0.5 ? 'l' : 'r');

// Verbatim from the quiz frontmatter.
const RECLAIM_PRIORITY = ['q3', 'q1', 'q2'];
const REDIRECT_PRIORITY = ['q2', 'q4', 'q7', 'q8', 'q5', 'q6'];
const RECLAIM_SENTENCE = {
  'q1:0': 'Reclaim the time. Running the events is the first place to lean on a tool or trim back. It’s expensive because it takes time away from the real value of facilitation and coaching.',
  'q3:0': 'Reclaim the time. That block of admin is the first thing to automate or simply stop doing. Use the time saved to coach the team or work on a systemic problem.',
  'q3:3': 'Reclaim the time. Automate or drop as much of the administrative overhead as possible, and put what you get back into mentoring and coaching.',
  'q2:0': 'Reclaim the time. Being the status-and-logistics desk is the first thing to hand off or automate. Take that time and put it towards coaching and facilitation.',
};
const REDIRECT_SENTENCE = {
  'q2:3': 'Start by finding out why people don’t come to you. Ask two or three of them privately.',
  'q4:0': 'Put that time into coaching. Real growth in a team happens not through a faster Daily Scrum, but through a team that learns to collaborate.',
