    responses: { q1: 3, q2: 1, q3: 3, q4: 3, q5: 1, q6: 0, q7: 3, q8: 2, q9: 3 },
  },
];

// --- the real selection logic, ported from map-move.ts ---------------------
function computeMove(responses, { withQ9 = false } = {}) {
  const questions = withQ9 ? [...QUESTIONS, CANDIDATE_Q9] : QUESTIONS;
  const byQ = {};
  const points = [];
  for (const q of questions) {
    const i = responses[q.id];
    if (i === undefined) continue;
    const p = { qid: q.id, idx: i, ...q.options[i] };
    byQ[q.id] = p;
    points.push(p);
  }
  const sentence = (p, kind) =>
    (kind === 'reclaim' ? RECLAIM_SENTENCE : REDIRECT_SENTENCE)[`${p.qid}:${p.idx}`];
  const eligible = (p, kind) =>
    p.bucket === 'slipping' || (p.bucket === 'context' && !!sentence(p, kind));
  const first = (priority, kind, exclude) => {
    for (const qid of priority) {
      const p = byQ[qid];
      if (p && eligible(p, kind) && p.qid !== exclude) return p;
    }
    return null;
  };
  const reclaim = first(RECLAIM_PRIORITY, 'reclaim');
  const redirect = first(REDIRECT_PRIORITY, 'redirect', reclaim?.qid);

  // Attention that landed in each box, and the answers that put it there.
  const weight = { tl: 0, tr: 0, bl: 0, br: 0 };
  const contents = { tl: [], tr: [], bl: [], br: [] };
  for (const p of points) {
    weight[boxOf(p)] += p.attn;
    contents[boxOf(p)].push(p);
  }
  for (const k of BOX_ORDER) contents[k].sort((a, b) => b.attn - a.attn);
  const total = Object.values(weight).reduce((a, b) => a + b, 0) || 1;

  return {
    points,
    reclaim,
    redirect,
    reclaimText: reclaim ? sentence(reclaim, 'reclaim') : undefined,
    redirectText: redirect ? sentence(redirect, 'redirect') : undefined,
    weight,
    contents,
    total,
    share: Object.fromEntries(BOX_ORDER.map((k) => [k, weight[k] / total])),
  };
}

// --- shared svg helpers ----------------------------------------------------
const esc = (s) =>
  String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function arrowDefs(id) {
  return `<defs><marker id="${id}" viewBox="0 0 10 10" refX="9" refY="5"
    markerWidth="6" markerHeight="6" orient="auto-start-reverse">
    <path d="M0,0 L10,5 L0,10 z" fill="${C.accStrong}"/></marker></defs>`;
}

function moveArrow(a, b, uid, lift) {
  if (!a || !b) return '';
  const dx = (b.x - a.x) * 0.35;
  return `<path d="M ${a.x} ${a.y} C ${a.x + dx} ${a.y - lift}, ${b.x - dx} ${b.y + lift}, ${b.x} ${b.y}"
    fill="none" stroke="${C.accStrong}" stroke-width="2.5"
    stroke-linecap="round" marker-end="url(#${uid})"/>`;
}

// Tint and ink per box, so the four kinds of work are always the same colour.
const BOX_STYLE = {
  tl: { tint: C.valTint, ink: C.valStrong, bar: C.valEdge },
  tr: { tint: C.valTint, ink: C.valStrong, bar: C.valEdge },
  bl: { tint: C.ctxPanel, ink: C.ink2, bar: C.ink3 },
  br: { tint: C.slipTint, ink: C.slipStrong, bar: C.slipEdge },
};

