// Greedy wrap using an average glyph width for Noto Sans. Good enough for
// a mockup; a real implementation would measure with getComputedTextLength.
function wrapLabel(text, maxWidth, fontSize) {
  const charW = fontSize * 0.5;
  const lines = [];
  let line = '';
  for (const word of text.split(' ')) {
    const next = line ? `${line} ${word}` : word;
    if (line && next.length * charW > maxWidth) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  }
  if (line) lines.push(line);
  return lines;
}

// Shared axis furniture: four text elements, and that is the whole frame.

