node -e "
const fs=require('fs');
const model=fs.readFileSync('temp/quiz-model.js','utf8');
const html=fs.readFileSync('temp/quiz-result-explore.html','utf8');
const js=html.split(/<script(?![^>]*src)[^>]*>/)[1].split('</script>')[0];

// Minimal DOM shim: enough to run render() and capture what it writes.
const shim = \`
const __els={};
function __el(id){ return __els[id] ||= {id, checked:false, _html:'',
  set innerHTML(v){ this._html=v; __check(v); }, get innerHTML(){return this._html;},
  insertAdjacentHTML(p,v){ this._html+=v; __check(v); },
  addEventListener(){}, dataset:{} }; }
const document={ getElementById:__el };
function __check(v){ const m=String(v).match(/undefined|NaN/); if(m) throw new Error('bad output near: '+String(v).slice(Math.max(0,String(v).indexOf(m[0])-140), String(v).indexOf(m[0])+60)); }
\`;

const src = model + shim + js + \`
globalThis.__probe=(resp,q9)=>{ responses={...resp}; __el('q9').checked=q9; render();
  return {out:__el('out').innerHTML, shares:__el('shares').innerHTML}; };
globalThis.__PRESETS=PRESETS; globalThis.__Q=QUESTIONS; globalThis.__CQ=CANDIDATE_Q9;
\`;
new Function(src)();

let n=0, noMove=0, evicted=0;
const run=(resp,q9)=>{ const r=globalThis.__probe(resp,q9); n++;
  if(!/where I.d start/.test(r.out)) throw new Error('missing move block');
  if((r.out.match(/<svg/g)||[]).length!==2) throw new Error('expected 2 svgs');
  if(/no redirect sentence|no reclaim sentence/.test(r.out)) noMove++;
  if(/Too small to label/.test(r.out)) evicted++;
};
for (const q9 of [false,true]) for (const p of globalThis.__PRESETS) run(p.responses,q9);
// Random sweep across the whole answer space.
const qs=[...globalThis.__Q, globalThis.__CQ];
for (let i=0;i<400;i++){ const r={}; for(const q of qs) r[q.id]=Math.floor(Math.random()*q.options.length); run(r, i%2===0); }
console.log('sets rendered OK:', n);
console.log('  sets with a missing move sentence:', noMove);
console.log('  sets where C3 evicted a label:', evicted, '('+Math.round(evicted/n*100)+'%)');
"

