// --- the real selection logic, ported from map-move.ts ---------------------
/**
 * `requireSentence` is the proposed fix to `eligible()` in map-move.ts. Today a
 * slipping answer is eligible for a half of the move whether or not a sentence
 * exists for that half, so `q2` opt0 (first in `redirectPriority`, no
 * `redirectSentence`) wins the redirect and the walk stops there. Requiring the
 * sentence — already the rule for `context` answers — lets the walk carry on to
 * the next candidate that has something to say.
 *
 * Both selections are returned: the fixed one drives the result, `raw*` is what
 * today's engine picks, so the mockup can show the difference rather than hide
 * it.
 */
function computeMove(responses, { withQ9 = false, requireSentence = true } = {}) {
  const questions = withQ9 ? [...QUESTIONS, CANDIDATE_Q9] : QUESTIONS;
  const byQ = {};
  const points = [];
  for (const q of questions) {
    const i = responses[q.id];
    if (i === undefined) continue;
    const p = { qid: q.id, idx: i, ...q.options[i] };
    byQ[q.id] = p;
    points.push(p);
  }
  const sentence = (p, kind) =>
    (kind === 'reclaim' ? RECLAIM_SENTENCE : REDIRECT_SENTENCE)[`${p.qid}:${p.idx}`];
  const eligible = (p, kind, needSentence) =>
    (p.bucket === 'slipping' && (!needSentence || !!sentence(p, kind))) ||
    (p.bucket === 'context' && !!sentence(p, kind));
  const first = (priority, kind, exclude, needSentence) => {
    for (const qid of priority) {
      const p = byQ[qid];
      if (p && eligible(p, kind, needSentence) && p.qid !== exclude) return p;
    }
    return null;
  };
  const reclaim = first(RECLAIM_PRIORITY, 'reclaim', undefined, requireSentence);
  const redirect = first(
    REDIRECT_PRIORITY,
    'redirect',
    reclaim?.qid,
    requireSentence
  );
  // What today's engine would pick, for the diagnostic readout.
  const rawReclaim = first(RECLAIM_PRIORITY, 'reclaim', undefined, false);
  const rawRedirect = first(REDIRECT_PRIORITY, 'redirect', rawReclaim?.qid, false);

