/**
 * Answer sets travel between the mockup pages in the SAME encoding the live
 * results page uses (`buildMapMoveQuery` / `parseMapMoveResponses` in
 * map-move.ts): an `a` param of `qid-index` pairs joined by dots. So a real
 * results URL can be pasted straight into the explore page, and a set found
 * here can be pasted into a real one.
 */
function encodeSet(responses, questions) {
  return questions
    .filter((q) => responses[q.id] !== undefined)
    .map((q) => `${q.id}-${responses[q.id]}`)
    .join('.');
}

function decodeSet(raw) {
  const responses = {};
  if (!raw) return responses;
  for (const pair of raw.split('.')) {
    const sep = pair.lastIndexOf('-');
    if (sep <= 0) continue;
    const id = pair.slice(0, sep);
    const index = parseInt(pair.slice(sep + 1), 10);
    if (id && Number.isInteger(index) && index >= 0) responses[id] = index;
  }
  return responses;
}

