 * MapMoveResults.astro:81-88 over every possible answer set, using the live
 * engine and the live frontmatter.
 */
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { computeMapMove } from '../src/lib/quiz-engine/map-move';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const quiz: any = parse(raw.split('---')[1]);
const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');
const mm = quiz.mapMove;

const tally: Record<string, number> = {
  wellPositioned: 0, move: 0, halfMove: 0, noMove: 0, none: 0,
};
let total = 0;
// Of the sets that fall through to the `noMove` copy, how many actually
// answered in the middle on every question, which is what that copy claims?
let noMoveTruthful = 0, noMoveLying = 0;

function walk(i: number, resp: Record<string, number>) {
  if (i === scored.length) {
    total++;
    const r = computeMapMove(quiz, resp);
    const halves = [r.reclaim?.sentence, r.redirect?.sentence].filter(Boolean).length;
    if (r.wellPositioned && mm?.wellPositioned) tally.wellPositioned++;
    else if (halves === 2) tally.move++;
    else if (halves === 1) tally.halfMove++;
    else if (mm?.noMove) {
      tally.noMove++;
      const allMixed = scored.every((q: any) => q.options[resp[q.id]]?.bucket === 'mixed');
      if (allMixed) noMoveTruthful++; else noMoveLying++;
    } else tally.none++;
    return;
  }
  for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
}
