console.log(`  "you landed in the middle"   ${pc(tally.noMove).padStart(7)}`);
console.log(`  nothing rendered at all      ${pc(tally.none).padStart(7)}`);
console.log(`\n  of the "you landed in the middle" sets:`);
console.log(`    genuinely answered all-mixed  ${noMoveTruthful.toLocaleString()}`);
console.log(`    did NOT, so the copy is false ${noMoveLying.toLocaleString()}`);
