/**
 * Same census, but comparing live behaviour with the two proposed changes
 * applied to an in-memory copy of the quiz. Nothing on disk is modified.
 */
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { computeMapMove } from '../src/lib/quiz-engine/map-move';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const base: any = parse(raw.split('---')[1]);

function census(quiz: any, fixEligibility: boolean) {
  const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');
  const t = { move: 0, halfMove: 0, wellPositioned: 0, noMove: 0, none: 0 };
  let total = 0;
  const walk = (i: number, resp: Record<string, number>) => {
    if (i === scored.length) {
      total++;
      const r = computeMapMove(quiz, resp);
      // The eligibility fix: a target only counts if its sentence exists.
      // Approximated here by ignoring a target whose sentence is missing, then
      // re-walking the priority list for the next one that has one.
      let reclaim = r.reclaim?.sentence ? r.reclaim : null;
      let redirect = r.redirect?.sentence ? r.redirect : null;
      if (fixEligibility && !redirect) {
        for (const qid of quiz.mapMove.redirectPriority) {
          if (qid === reclaim?.entry.questionId) continue;
          const idx = resp[qid];
          const opt = quiz.questions.find((q: any) => q.id === qid)?.options[idx];
          if (!opt?.redirectSentence) continue;
          if (opt.bucket === 'slipping' || opt.bucket === 'context') {
            redirect = { entry: { questionId: qid }, sentence: opt.redirectSentence } as any;
            break;
          }
        }
      }
      const halves = [reclaim?.sentence, redirect?.sentence].filter(Boolean).length;
      // wellPositioned is suppressed when a context answer wins either half.
      const wp = r.wellPositioned && !reclaim && !redirect;
      if (wp && quiz.mapMove?.wellPositioned) t.wellPositioned++;
      else if (halves === 2) t.move++;
      else if (halves === 1) t.halfMove++;
      else if (quiz.mapMove?.noMove) t.noMove++;
      else t.none++;
      return;
    }
    for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
  };
  walk(0, {});
  return { t, total };
}

const proposed = JSON.parse(JSON.stringify(base));
proposed.questions.find((q: any) => q.id === 'q1').options[3].reclaimSentence =
  'Reclaim the time. When the role only gets part of your week, running the events is the most expensive thing in it. Trim it back or lean on a tool, and put what you get back into the people.';

const rows: [string, any][] = [
  ['live today', census(base, false)],
  ['+ eligibility fix', census(base, true)],
  ['+ eligibility fix + q1 sentence', census(proposed, true)],
];
const pc = (x: number, n: number) => ((x / n) * 100).toFixed(1).padStart(5) + '%';
console.log('what the payoff block renders, over all 65,536 answer sets\n');
console.log('                                   both    half   rare   middle  nothing');
for (const [name, { t, total }] of rows) {
  console.log(
    name.padEnd(33) +
      [t.move, t.halfMove, t.wellPositioned, t.noMove, t.none]
        .map((x) => pc(x, total))
        .join(' ')
  );
}
EOF
