toolUseResult.originalFile:
export type MapMoveBucket = 'gaining' | 'mixed' | 'slipping' | 'context';

export interface QuizOption {
  text: string;
  score: number;
  /**
   * Concept icon shown beside this answer's sentence in the map (see
   * `QuizIcon`'s vocabulary). Reinforces the colour, never carries meaning alone.
   */
  icon?: string;
  /**
   * map-move classification for this answer. `'context'` marks a real-world
   * constraint that must not be scored as a gap. Ignored by the band style.
   */
  bucket?: MapMoveBucket;
  /** Line shown for this answer in the map (gaining/slipping column or context notes). */
  mapSentence?: string;
  /** Shown when this answer is chosen as the reclaim target of the one move. */
  reclaimSentence?: string;
  /** Shown when this answer is chosen as the redirect target of the one move. */
  redirectSentence?: string;
  /**
   * Tag applied to the submission when this answer is chosen, sent alongside
   * the host's static tags as `tags[<name>]=true`. Use on a `profile` question
   * to segment the list by who the taker is.
   */
  tag?: string;
  /**
   * A standing instruction for the rest of the quiz, shown from the moment this
   * answer is chosen and repeated above every later question. Use when an answer
   * changes *who the remaining questions are about* — e.g. a manager who should
   * answer for the person doing the role rather than for themselves. Without the
   * repeat it would be forgotten by question three.
   */
  lens?: string;
}

/**
 * What a question is for.
 * - `'scored'` (default): a real question. Scored, mapped, counted in progress.
 * - `'profile'`: classifies the taker rather than assessing them. Contributes
 *   nothing to the score or the map, carries no progress (so a quiz that
 *   promises "eight questions" still has eight), and always leads, ahead of any
 *   randomization. Its job is to set `tag` and/or `lens`.
 */
export type QuizQuestionKind = 'scored' | 'profile';

export interface QuizQuestion {
  id: string;
  section: string;
  text: string;
  reveal?: string;
  /**
   * Small text above the question, in place of the section label. A `profile`
   * question has no declared section, so without this it is the only screen in
   * the quiz with nothing above the heading, and nothing to say it isn't one of
   * the questions the cover promised.
   */
  label?: string;
  /** Defaults to `'scored'`. */
  kind?: QuizQuestionKind;
  options: QuizOption[];
}

/** True for questions that count toward the score, the map and the progress bar. */
export function isScored(question: QuizQuestion): boolean {
  return (question.kind ?? 'scored') === 'scored';
}

import type { ImageMetadata } from 'astro';

export interface QuizSection {
  id: string;
  label: string;
  blurb?: string;
  /**
   * Optional image rendered alongside the section card on the landing page.
   * `ImageMetadata` when the frontmatter uses a content-relative path
   * (Astro's `image()` helper resolves and optimizes it), or a plain string
   * for remote URLs and paths served from `public/`.
   */
  image?: string | ImageMetadata;
}

export interface QuizLevelThreshold {
  level: string;
  minScore: number;
  maxScore: number;
  title?: string;
}

/**
 * Selects the results-rendering strategy.
 * - `'band'` (default): total score maps to a level; `<ResultCard>` blocks render.
