import { isScored } from './types';
import type {
  MapMoveEntry,
  MapMoveResult,
  QuizData,
  QuizResponses,
} from './types';

/**
 * Pure logic for the `map-move` result style. Given the taker's responses, it
 * classifies each answer into gaining / slipping / context buckets, then picks
 * the single reclaim + redirect move from the quiz's priority ordering. All
 * copy lives in the quiz frontmatter; this module only decides which answers
 * and which move to surface.
 */
export function computeMapMove(
  quiz: QuizData,
  responses: QuizResponses
): MapMoveResult {
  const gaining: MapMoveEntry[] = [];
  const slipping: MapMoveEntry[] = [];
  const context: MapMoveEntry[] = [];
  // Keyed by question id so the move selection can look answers up by priority.
  const byQuestion = new Map<string, MapMoveEntry>();

  for (const question of quiz.questions) {
    const optionIndex = responses[question.id];
    if (optionIndex === undefined) continue;
    // Profile answers say who the taker is, not how their sprints went. Keeping
    // them out here is what stops "I'm a project manager" turning up as a line
    // in the context strip and skewing the balance bar. They stay in the results
    // query (see buildMapMoveQuery) so the page could branch on them later.
    if (!isScored(question)) continue;
    const option = question.options[optionIndex];
    if (!option) continue;

    const entry: MapMoveEntry = {
      questionId: question.id,
      optionIndex,
      bucket: option.bucket ?? 'mixed',
      sentence: option.mapSentence,
    };
    byQuestion.set(question.id, entry);

    if (entry.bucket === 'gaining') gaining.push(entry);
    else if (entry.bucket === 'slipping') slipping.push(entry);
    else if (entry.bucket === 'context') context.push(entry);
    // 'mixed' answers do not appear in the map.
  }

  const config = quiz.mapMove;
  const reclaimPriority = config?.reclaimPriority ?? [];
  const redirectPriority = config?.redirectPriority ?? [];

  /**
   * A `context` answer is never a gap, so it stays out of the map's problem
   * column and out of the balance. But some constraints are real problems the
   * taker cannot ignore (no Product Owner to reach, impediments that never
   * surface, admin that doesn't shrink just because the role is part-time), and
   * leaving those in the soft context strip understates them: "not your fault"
   * is not the same as "not important". When such an answer supplies the
   * sentence for a move, it can win that move, so the problem lands in the most
   * prominent block on the page without anyone being blamed for it.
   *
   * The sentence is the opt-in: an author who writes one has decided this
   * constraint is actionable. Without it the answer stays in the context strip.
   */
  const eligible = (
    entry: MapMoveEntry,
    field: 'reclaimSentence' | 'redirectSentence'
  ): boolean =>
    entry.bucket === 'slipping' ||
