import { type SchemaContext } from 'astro:content';
import { z } from 'astro/zod';

/**
 * Returns a Zod schema for a quiz content collection entry. Designed to be
 * called from the function-form `schema:` callback of `defineCollection` so
 * the Astro `image()` helper can be threaded through to image-bearing fields.
 *
 *   import { createQuizSchema } from '@/lib/quiz-engine';
 *
 *   const quizzes = defineCollection({
 *     loader: glob({ pattern: '**\/*.mdx', base: './src/content/quizzes' }),
 *     schema: (ctx) => createQuizSchema(ctx),
 *   });
 *
 * Consumers can `.extend()` the returned schema to add site-specific fields
 * without touching the engine.
 */
export function createQuizSchema({ image }: SchemaContext) {
  const threshold = z.object({
    level: z.string(),
    minScore: z.number().int().nonnegative(),
    maxScore: z.number().int().nonnegative(),
    title: z.string().optional(),
  });

  // Copy + selection config for the `map-move` result style. Everything here is
  // generic (no site-specific wording is baked into the engine); the author
  // supplies the strings in frontmatter and the `MapMoveResults` component
  // renders them around the computed map. Only used when `resultStyle` is
  // `'map-move'`.
  const mapMove = z.object({
    // Question ids in priority order. The `reclaim` move points at the
    // highest-priority question whose chosen answer is in the `slipping`
    // bucket; `redirect` does the same over its own ordered list.
    reclaimPriority: z.array(z.string()).default([]),
    redirectPriority: z.array(z.string()).default([]),
    eyebrow: z.string().optional(),
    // The result heading. Keep it descriptive: this style never grades anyone,
    // so no tier title and no archetype here.
    heading: z.string().optional(),
    opening: z.string().optional(),
    // Label above the balance bar (the lead visual: proportion, never a score).
    balanceLabel: z.string().optional(),
    gainingHeading: z.string(),
    // Shown in the gaining/slipping columns when that column is empty.
    gainingEmpty: z.string().optional(),
    slippingHeading: z.string(),
    slippingEmpty: z.string().optional(),
    moveHeading: z.string().optional(),
    contextHeading: z.string().optional(),
    // Body shown instead of the reclaim/redirect move when nothing is slipping.
    wellPositioned: z.string().optional(),
    // Body shown when nothing was decisive enough to point at (every answer in
    // the middle). Omit it and the payoff block is dropped rather than rendered
    // as an empty box.
    noMove: z.string().optional(),
    close: z.string().optional(),
    // Light, descriptive framing line above the map. The engine picks one of
    // the three based on the ratio of gaining to slipping answers. Never an
    // archetype or score.
    framing: z
      .object({
        gaining: z.string(),
        mixed: z.string(),
        slipping: z.string(),
      })
      .optional(),
    // Footer row: one line of secondary text plus an accent link.
    cta: z
      .object({
        body: z.string().optional(),
        buttonLabel: z.string(),
        buttonHref: z.string(),
      })
      .optional(),
  });

  return z.object({
    title: z.string(),
    description: z.string().optional(),
    intro: z.string().optional(),
    resultsSubtitle: z.string().optional(),
    // Selects the results-rendering strategy. `'band'` (default) maps a total
    // score into a level and renders `<ResultCard>` blocks. `'map-move'`
    // renders a per-answer map plus one recommended move (see `mapMove`).
    resultStyle: z.enum(['band', 'map-move']).default('band'),
    // Where the email capture sits. `'end'` (default) asks after the last
    // question; `'start'` makes it a hard gate before question 1. A start gate
    // runs before anything is answered, so `levelTagPrefix` has no result to
    // tag with and is ignored.
    capturePosition: z.enum(['start', 'end']).default('end'),
    // Cover strip showing what the taker gets, before they hand anything over.
    // Each chip is tinted by `tone` purely for warmth and sequence.
    howItWorks: z
      .array(
        z.object({
          label: z.string().optional(),
          title: z.string(),
          body: z.string().optional(),
          icon: z.string().optional(),
          tone: z
            .enum(['accent', 'valuable', 'slipping', 'alt'])
            .default('accent'),
        })
      )
      .optional(),
    sections: z
      .array(
        z.object({
          id: z.string(),
          label: z.string(),
          blurb: z.string().optional(),
          image: image().or(z.string()).optional(),
        })
      )
      .min(1),
    questions: z
      .array(
        z.object({
          id: z.string(),
          section: z.string(),
          text: z.string(),
          reveal: z.string().optional(),
          // Small text above the question, in place of the section label.
          label: z.string().optional(),
          // 'profile' classifies the taker instead of assessing them: no score,
          // no map entry, no progress, always asked first. Use it to set an
          // option's `tag` and/or `lens`.
          kind: z.enum(['scored', 'profile']).optional(),
          options: z
            .array(
              z.object({
                text: z.string(),
                score: z.number().int(),
                // Concept icon shown beside this answer's sentence in the map.
                icon: z.string().optional(),
                // map-move classification. `context` marks a real-world
                // constraint (e.g. part-time role) that must NOT be counted as
                // a gap. Ignored by the band style.
                bucket: z
                  .enum(['gaining', 'mixed', 'slipping', 'context'])
                  .optional(),
                // The line shown for this answer in the map (gaining column,
                // slipping column, or the context notes). Omit for `mixed`.
                mapSentence: z.string().optional(),
                // Shown when this answer is selected as the reclaim / redirect
                // target of the one move.
                reclaimSentence: z.string().optional(),
                redirectSentence: z.string().optional(),
                // Tag applied to the submission when this answer is chosen.
                tag: z.string().optional(),
                // Standing instruction shown from the moment this answer is
                // chosen and above every later question, for answers that change
                // who the rest of the quiz is about.
                lens: z.string().optional(),
              })
            )
            .min(2),
        })
      )
      .min(1),
    // Band-style scoring bands. Optional so `map-move` quizzes can omit them.
    sectionLevels: z.array(threshold).min(1).optional(),
    overallLevels: z.array(threshold).min(1).optional(),
    mapMove: mapMove.optional(),
    randomize: z.enum(['none', 'within-sections']).default('none'),
    // Controls the order options are shown in within a question. `'shuffle'`
    // randomizes them per visit so a fixed slipping→mixed→gaining→context order
    // never telegraphs the "best" answer. Scoring is keyed by the option's
    // original index, so this affects presentation only.
    randomizeOptions: z.enum(['none', 'shuffle']).default('none'),
  });
}

