---
/**
 * The map-move lead visual: a two-row mosaic where every named kind of work is
 * drawn at the size of the time the taker gave it. Rows are sized by their
 * combined share, boxes within a row by their share of that row, so the areas
 * are the proportions and nothing is clamped to fit a label.
 *
 * It replaced a single two-segment balance bar. The bar could only say "this
 * much of your time was well spent"; the mosaic says which kinds of work the
 * time went to, which is what makes one area worth more attention than another.
 *
 * Three rules it has to keep:
 *
 * - **No number anywhere.** Size carries the proportion. The result is a map of
 *   where the time went, not a grade.
 * - **No arrow.** The move is marked with two or three accent words on the two
 *   boxes involved (`tagFrom` / `tagTo`). A curve across the picture was hard
 *   to follow and made the whole thing busy.
 * - **Names name the work, never the person.** "the people work", not "the
 *   Coach". An archetype is the thing this quiz refuses to hand out.
 *
 * Built in HTML rather than SVG on purpose: an SVG's text scales with its
 * viewBox, so a 15px label renders at about 8px on a phone. Percentage-sized
 * flex boxes give the same geometry with real, responsive text.
 */
import type { MapMoveShape, MapMoveShapeConfig } from '../types';

interface Props {
  config: MapMoveShapeConfig;
  shape: MapMoveShape;
  /** Box holding the reclaim target, tagged with `tagFrom`. */
  fromBoxId?: string;
  /** Box holding the redirect target, tagged with `tagTo`. */
  toBoxId?: string;
}

const { config, shape, fromBoxId, toBoxId } = Astro.props;

const shareOf = (id: string) =>
  shape.boxes.find((b) => b.boxId === id)?.share ?? 0;

const nameOf = (id: string) =>
  config.boxes.find((b) => b.id === id)?.name ?? id;

/**
 * A box needs room for its own name. Below these thresholds the name moves to
 * the key underneath rather than being clipped or shrunk: the mosaic keeps
 * telling the truth about the proportions, and nothing goes missing.
 *
 * Fixed fractions rather than measured pixels, because the geometry is
 * percentage-based and identical at every viewport.
 */
const MIN_ROW_SHARE = 0.15;
const MIN_WIDTH_SHARE = 0.28;

const rows = (['top', 'bottom'] as const)
  .map((row) => {
    const boxes = config.boxes.filter((b) => b.row === row);
    const share = boxes.reduce((sum, b) => sum + shareOf(b.id), 0);
    return { row, boxes, share };
  })
  // A row nobody spent time on is not drawn at all. Its boxes are named in the
  // key instead, which is how an empty box stops being a hole in the picture.
  .filter((r) => r.boxes.length > 0 && r.share > 0);

const drawn = rows.flatMap((r) =>
  r.boxes
    .filter((b) => shareOf(b.id) > 0)
    .map((b) => ({
      box: b,
      widthShare: shareOf(b.id) / r.share,
      rowShare: r.share,
    }))
);

const labelledInside = new Set(
  drawn
    .filter(
      (d) => d.rowShare >= MIN_ROW_SHARE && d.widthShare >= MIN_WIDTH_SHARE
    )
    .map((d) => d.box.id)
);

/**
 * Boxes whose name is not on the picture: too small to hold it, or nobody spent
 * any time there so they were not drawn. Shown as a swatch-and-name legend, so
 * the tint is what ties an entry back to its sliver. Carries no wording of its
 * own, which is what keeps the engine free of site-specific English.
 */
const keyItems = config.boxes.filter((b) => !labelledInside.has(b.id));

const TONE: Record<string, string> = {
  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
  context: 'bg-quiz-context-panel text-quiz-ink-secondary',
};

const SWATCH: Record<string, string> = {
  valuable: 'bg-quiz-valuable-edge',
  slipping: 'bg-quiz-slipping-edge',
  context: 'bg-quiz-ink-muted',
};

// The one place a percentage is spoken: a screen reader gets nothing from the
// geometry, so the shares have to be said out loud somewhere.
const ariaLabel = config.boxes
  .map((b) => `${b.name} ${Math.round(shareOf(b.id) * 100)}%`)
  .join(', ');

const readingLines = [
  config.mostLine?.replace('{box}', nameOf(shape.largestBoxId)),
  shape.topShare >= 0.5 ? config.mostlyTop : config.mostlyBottom,
].filter(Boolean) as string[];
---

