  {
    config.label ? (
      <figcaption class="text-quiz-ink-secondary mb-3 text-sm">
        {config.label}
      </figcaption>
    ) : null
  }

  <p class="text-quiz-valuable-strong mb-2 text-center text-xs">
    {config.axisTop}
  </p>

  <div
    class="flex h-80 flex-col gap-1 md:h-96"
    role="img"
    aria-label={ariaLabel}
  >
    {
      rows.map((r) => (
        <div class="flex gap-1" style={`height:${r.share * 100}%`}>
          {r.boxes
            .filter((b) => shareOf(b.id) > 0)
            .map((b) => (
              <div
                class={`${TONE[b.tone]} flex items-start justify-between gap-2 overflow-hidden rounded-xl px-3 py-2.5 md:px-4 md:py-3`}
                style={`width:${(shareOf(b.id) / r.share) * 100}%`}
