import { computeMapMove } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';
import MapMoveShape from './MapMoveShape.astro';
import QuizIcon from './QuizIcon';

toolUseResult.originalFile:
---
/**
 * Renders the `map-move` result style: a per-answer map (work getting more
 * valuable vs. work a tool can take) plus one recommended move. Everything the
 * component prints comes from the quiz's `mapMove` frontmatter and the chosen
 * options' sentences, so the engine stays free of any site-specific wording.
 *
 * The design is a map, not a grade. There is no number, letter or tier title
 * anywhere on the page: the lead visual is a proportion bar, and colour is
 * always backed by an icon, a label and a position so it survives greyscale and
 * colour-blindness. Surfaces are flat with hairline borders; the one move is
 * the single block allowed a heavier border, because it is the payoff.
 *
 * The page passes the taker's decoded responses; scoring/selection happens in
 * `computeMapMove`. This component is presentation only.
 */
import { computeMapMove } from '../map-move';
import type { MapMoveEntry, QuizData, QuizResponses } from '../types';
import QuizIcon from './QuizIcon';

interface Props {
  quiz: QuizData;
  responses: QuizResponses;
}

const { quiz, responses } = Astro.props;
const mm = quiz.mapMove;
const result = computeMapMove(quiz, responses);

// Minimal, escaped inline markdown: `[label](url)` links only. Content is
// author-controlled (frontmatter), but escaping first keeps this safe if that
// ever changes.
function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderInline(text: string): string {
  return escapeHtml(text).replace(
    /\[([^\]]+)\]\(([^)\s]+)\)/g,
    (_m, label: string, url: string) => {
      const external = /^https?:\/\//i.test(url);
      const attrs = external
        ? ` target="_blank" rel="noopener noreferrer"`
        : '';
      return `<a href="${url}"${attrs} class="text-quiz-accent-strong underline">${label}</a>`;
    }
  );
}

function paragraphs(text?: string): string[] {
  if (!text) return [];
  return text
    .split(/\n\s*\n/)
    .map((p) => p.trim())
    .filter(Boolean);
}

// Each answer's icon comes from the option the taker chose, so the map reads as
// concepts rather than bullets.
function iconFor(entry: MapMoveEntry): string | undefined {
  const question = quiz.questions.find((q) => q.id === entry.questionId);
  return question?.options[entry.optionIndex]?.icon;
}

const heading = mm?.heading ?? quiz.title;

// A context answer with no `mapSentence` has nothing to say. Filtering here
// rather than in the loop also keeps the panel itself from rendering as a bare
// heading over an empty list.
const contextWithSentences = result.context.filter((entry) => entry.sentence);

/**
 * What the payoff block should say. `'none'` drops the block entirely rather
 * than printing an accent-bordered box containing only its heading, which is
 * what a taker who answered in the middle of every question used to get: no
 * move to make, but not well positioned either, so neither branch had copy.
 */
const moveBody: 'wellPositioned' | 'move' | 'noMove' | 'none' =
  result.wellPositioned && mm?.wellPositioned
    ? 'wellPositioned'
    : result.reclaim?.sentence || result.redirect?.sentence
      ? 'move'
      : mm?.noMove
        ? 'noMove'
        : 'none';
---

<div class="mx-auto max-w-170">
  <header class="mb-8">
    {
      mm?.eyebrow ? (
        <p class="text-quiz-accent-strong mb-2 text-sm">{mm.eyebrow}</p>
      ) : null
    }
    <h1 class="text-quiz-ink text-2xl/tight font-bold md:text-3xl/tight">
      {heading}
    </h1>
    {
      paragraphs(mm?.opening).map((p) => (
        <p
          class="text-quiz-ink-secondary mt-4 text-base/relaxed"
          set:html={renderInline(p)}
        />
      ))
    }
  </header>

  {/* The lead visual: proportions, deliberately without a number on them. */}
  {
    mm?.shape && result.shape ? (
      <MapMoveShape
        config={mm.shape}
        shape={result.shape}
        fromBoxId={result.reclaim?.sentence ? result.reclaim.boxId : undefined}
        toBoxId={result.redirect?.sentence ? result.redirect.boxId : undefined}
      />
    ) : null
  }

  {/* The map: two columns, what is gaining and what a tool can take. */}
  <section class="mb-8 grid grid-cols-1 gap-3.5 md:grid-cols-2">
    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-valuable-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="gaining" size={18} />
        {mm?.gainingHeading}
      </h2>
      {
        result.gaining.length > 0 ? (
          <ul class="space-y-3">
            {result.gaining.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-valuable-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.gainingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">{mm.gainingEmpty}</p>
        ) : null
      }
    </div>

    <div
      class="border-quiz-hairline bg-quiz-card rounded-xl border-[0.5px] p-4 md:px-5"
    >
      <h2
        class="text-quiz-slipping-strong mb-3 flex items-center gap-2 text-lg font-bold"
      >
        <QuizIcon name="slipping" size={18} />
        {mm?.slippingHeading}
      </h2>
      {
        result.slipping.length > 0 ? (
          <ul class="space-y-3">
            {result.slipping.map((entry) => (
              <li class="flex items-start gap-2.5">
                <span class="text-quiz-slipping-strong mt-0.5 shrink-0">
                  <QuizIcon name={iconFor(entry) ?? ''} size={18} />
                </span>
                <span
                  class="text-quiz-ink text-base/relaxed"
                  set:html={renderInline(entry.sentence ?? '')}
                />
              </li>
            ))}
          </ul>
        ) : mm?.slippingEmpty ? (
          <p class="text-quiz-ink-muted text-base/relaxed">
            {mm.slippingEmpty}
          </p>
        ) : null
      }
    </div>
  </section>

  {/* Context: the constraints. Visibly softer, and never counted as a gap. */}
  {
    contextWithSentences.length > 0 ? (
