/** Census of the rebuilt results page: shape, move coverage, label eviction. */
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { computeMapMove } from '../src/lib/quiz-engine/map-move';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const quiz: any = parse(raw.split('---')[1]);
const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');
const boxes = quiz.mapMove.shape.boxes;
const MIN_ROW = 0.15, MIN_WIDTH = 0.28;

const t = { move: 0, half: 0, rare: 0, middle: 0, none: 0 };
let total = 0, noShape = 0, evicted = 0, sumShares = 0, worstDrift = 0;
const largest: Record<string, number> = {};

function walk(i: number, resp: Record<string, number>) {
  if (i === scored.length) {
    total++;
    const r = computeMapMove(quiz, resp);
    const halves = [r.reclaim?.sentence, r.redirect?.sentence].filter(Boolean).length;
    if (r.wellPositioned && quiz.mapMove?.wellPositioned) t.rare++;
    else if (halves === 2) t.move++;
    else if (halves === 1) t.half++;
    else if (quiz.mapMove?.noMove) t.middle++;
    else t.none++;

    if (!r.shape) { noShape++; return; }
    largest[r.shape.largestBoxId] = (largest[r.shape.largestBoxId] ?? 0) + 1;
    const sum = r.shape.boxes.reduce((s: number, b: any) => s + b.share, 0);
    worstDrift = Math.max(worstDrift, Math.abs(sum - 1));
    sumShares++;

    // Replicate MapMoveShape's labelling rule.
    const shareOf = (id: string) => r.shape!.boxes.find((b) => b.boxId === id)!.share;
    let anyEvicted = false;
    for (const row of ['top', 'bottom']) {
      const inRow = boxes.filter((b: any) => b.row === row);
      const rowShare = inRow.reduce((s: number, b: any) => s + shareOf(b.id), 0);
      for (const b of inRow) {
        if (shareOf(b.id) === 0) { anyEvicted = true; continue; }
        if (rowShare < MIN_ROW || shareOf(b.id) / rowShare < MIN_WIDTH) anyEvicted = true;
      }
    }
    if (anyEvicted) evicted++;
    return;
  }
  for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
}
walk(0, {});

const pc = (x: number) => ((x / total) * 100).toFixed(1) + '%';
console.log(`all ${total.toLocaleString()} answer sets\n`);
console.log('payoff block:');
console.log(`  both halves of the move   ${pc(t.move).padStart(7)}`);
console.log(`  one half only             ${pc(t.half).padStart(7)}`);
console.log(`  "you're the rare case"    ${pc(t.rare).padStart(7)}`);
console.log(`  "you landed in the middle"${pc(t.middle).padStart(7)}`);
console.log(`  nothing rendered          ${pc(t.none).padStart(7)}`);
console.log('\nshape:');
console.log(`  sets with no shape to draw ${noShape}`);
console.log(`  shares sum to 1 (worst drift ${worstDrift.toExponential(1)})`);
console.log(`  a box name falls to the key ${pc(evicted)}`);
console.log('  biggest box:', Object.entries(largest).map(([k, v]) => `${k} ${pc(v)}`).join('  '));
EOF
