import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { computeMapMove } from '../src/lib/quiz-engine/map-move';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const quiz: any = parse(raw.split('---')[1]);
const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');
const boxes = quiz.mapMove.shape.boxes;

const minTopWidth: number[] = [];
const rowShares: number[] = [];
function walk(i: number, resp: Record<string, number>) {
  if (i === scored.length) {
    const r = computeMapMove(quiz, resp);
    if (!r.shape) return;
    const shareOf = (id: string) => r.shape!.boxes.find((b) => b.boxId === id)!.share;
    const top = boxes.filter((b: any) => b.row === 'top');
    const topShare = top.reduce((s: number, b: any) => s + shareOf(b.id), 0);
    const bottomShare = 1 - topShare;
    rowShares.push(Math.min(topShare, bottomShare));
    if (topShare > 0) minTopWidth.push(Math.min(...top.map((b: any) => shareOf(b.id) / topShare)));
    return;
  }
  for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
}
walk(0, {});

const q = (a: number[], p: number) => a.slice().sort((x, y) => x - y)[Math.floor(a.length * p)];
console.log('narrower top box, as a share of the top row:');
for (const p of [0.01, 0.05, 0.1, 0.25, 0.5]) console.log(`  ${(p * 100).toString().padStart(2)}th percentile  ${q(minTopWidth, p).toFixed(3)}`);
console.log('\nshorter row, as a share of the whole:');
for (const p of [0.01, 0.05, 0.1, 0.25, 0.5]) console.log(`  ${(p * 100).toString().padStart(2)}th percentile  ${q(rowShares, p).toFixed(3)}`);
console.log('\neviction rate by threshold (width / row):');
for (const w of [0.14, 0.18, 0.22, 0.28]) {
  const rate = minTopWidth.filter((x) => x < w).length / minTopWidth.length;
  console.log(`  width < ${w}  ->  ${(rate * 100).toFixed(1)}%`);
}
for (const rs of [0.06, 0.1, 0.15]) {
  const rate = rowShares.filter((x) => x < rs).length / rowShares.length;
  console.log(`  row   < ${rs}  ->  ${(rate * 100).toFixed(1)}%`);
}
