const MIN_ROW_SHARE = 0.1;
const MIN_WIDTH_SHARE = 0.26;

const rows = (['top', 'bottom'] as const)
  .map((row) => {
    const boxes = config.boxes.filter((b) => b.row === row);
    const share = boxes.reduce((sum, b) => sum + shareOf(b.id), 0);
    return { row, boxes, share };
  })
  // A row nobody spent time on is not drawn at all. Its boxes are named in the
  // key instead, which is how an empty box stops being a hole in the picture.
  .filter((r) => r.boxes.length > 0 && r.share > 0);

