---
/**
 * The map-move lead visual: a fixed grid of named kinds of work, each carrying a
 * bar showing how much of the taker's time went to it.
 *
 * It replaced a single two-segment balance bar. The bar could only say "this
 * much of your time was well spent"; this says which kinds of work the time went
 * to, which is what makes one area worth more attention than another.
 *
 * A true-proportion mosaic (boxes drawn at the size of their share) was built
 * first and rejected. It read beautifully on the common cases and then failed on
 * the one that matters: the box being recommended is by definition the one the
 * taker has given least time to, so it was always the smallest box on the
 * picture and always the first too small to hold its own label. The picture
 * argued against its own recommendation. Fixed boxes plus a bar say the same
 * thing about proportion while guaranteeing every box can be read.
 *
 * Three rules it has to keep:
 *
 * - **No number anywhere.** The bars carry the proportion. The result is a map
 *   of where the time went, not a grade.
 * - **No arrow.** The move is marked with two or three accent words on the two
 *   boxes involved (`tagFrom` / `tagTo`). A curve across the picture was hard to
 *   follow and made the whole thing busy.
 * - **Names name the work, never the person.** "the people work", not "the
 *   Coach". An archetype is the thing this quiz refuses to hand out.
 *
 * Built in HTML rather than SVG on purpose: an SVG's text scales with its
 * viewBox, so a 15px label renders at about 8px on a phone.
 */
import type { MapMoveShape, MapMoveShapeConfig } from '../types';

interface Props {
  config: MapMoveShapeConfig;
  shape: MapMoveShape;
  /** Box holding the reclaim target, tagged with `tagFrom`. */
  fromBoxId?: string;
  /** Box holding the redirect target, tagged with `tagTo`. */
  toBoxId?: string;
}

const { config, shape, fromBoxId, toBoxId } = Astro.props;

const shareOf = (id: string) =>
  shape.boxes.find((b) => b.boxId === id)?.share ?? 0;

const nameOf = (id: string) =>
  config.boxes.find((b) => b.id === id)?.name ?? id;

const rows = (['top', 'bottom'] as const)
  .map((row) => ({ row, boxes: config.boxes.filter((b) => b.row === row) }))
  .filter((r) => r.boxes.length > 0);

/**
 * Bars have to be comparable across boxes, and a row with one box makes that box
 * twice as wide as a box in a row of two. Left alone, a 24% share in the wide
 * box would draw the same length as a 48% share in a narrow one, which is
 * exactly backwards. Scaling each bar by its row's box count puts every bar on
 * one scale, so equal lengths mean equal shares wherever they sit.
 *
 * (The horizontal padding is the same in every box rather than scaled with it,
 * so a bar is off by at most ~12px on a 680px figure. Visible to a ruler, not to
 * a reader, and worth it to keep the boxes optically consistent.)
 */
const maxPerRow = Math.max(...rows.map((r) => r.boxes.length));
const barPercent = (id: string, boxesInRow: number) =>
  shareOf(id) * 100 * (boxesInRow / maxPerRow);

const TONE: Record<string, string> = {
  valuable: 'bg-quiz-valuable-tint text-quiz-valuable-strong',
  slipping: 'bg-quiz-slipping-tint text-quiz-slipping-strong',
  context: 'bg-quiz-context-panel text-quiz-ink-secondary',
};

const BAR: Record<string, string> = {
  valuable: 'bg-quiz-valuable-edge',
  slipping: 'bg-quiz-slipping-edge',
  context: 'bg-quiz-ink-muted',
};

// The one place a percentage is spoken: a screen reader gets nothing from bar
// lengths, so the shares have to be said out loud somewhere.
const ariaLabel = config.boxes
  .map((b) => `${b.name} ${Math.round(shareOf(b.id) * 100)}%`)
  .join(', ');

/**
 * The reading line. `mostlyTop` / `mostlyBottom` only print when they add
 * something: if the biggest box is already on the row where most of the time
 * went, naming that row restates the sentence before it ("Most of your Sprints
 * went to the mechanical work. Most of your time is in work the tools are
 * starting to do."). It earns its place when the two disagree, which is the
 * genuinely interesting case: one big box on one row, but the balance of
 * everything else on the other.
 */
const majorityRow = shape.topShare >= 0.5 ? 'top' : 'bottom';
const largestRow = config.boxes.find((b) => b.id === shape.largestBoxId)?.row;
const readingLines = [
  config.mostLine?.replace('{box}', nameOf(shape.largestBoxId)),
  largestRow !== majorityRow
    ? majorityRow === 'top'
      ? config.mostlyTop
      : config.mostlyBottom
    : undefined,
].filter(Boolean) as string[];
