                class={`${TONE[b.tone]} flex items-start justify-between gap-2 overflow-hidden rounded-xl px-3 py-2.5 md:px-4 md:py-3`}
                style={`width:${(shareOf(b.id) / r.share) * 100}%`}
              >
                {labelledInside.has(b.id) ? (
                  <>
                    <span class="text-sm font-medium wrap-break-word md:text-base">
                      {b.name}
                    </span>
                    {b.id === fromBoxId && config.tagFrom ? (
                      <span class="text-quiz-accent-strong shrink-0 text-xs font-medium">
                        {config.tagFrom}
                      </span>
                    ) : b.id === toBoxId && config.tagTo ? (
                      <span class="text-quiz-accent-strong shrink-0 text-xs font-medium">
                        {config.tagTo}
                      </span>
                    ) : null}
                  </>
                ) : null}
              </div>
            ))}
        </div>
      ))
    }
  </div>

  {
    config.axisNear || config.axisFar ? (
      <div class="text-quiz-ink-muted mt-2 flex justify-between text-xs">
        <span>{config.axisNear}</span>
        <span>{config.axisFar}</span>
      </div>
    ) : null
  }

  <p class="text-quiz-slipping-strong mt-1 text-center text-xs">
    {config.axisBottom}
  </p>

  {
    keyItems.length > 0 ? (
      <ul class="text-quiz-ink-muted mt-3 flex flex-wrap gap-x-4 gap-y-1 text-xs">
        {keyItems.map(({ box, tag }) => (
          <li class="flex items-center gap-1.5">
            <span
              class={`${SWATCH[box.tone]} inline-block size-2 shrink-0 rounded-full`}
              aria-hidden="true"
            />
            {box.name}
            {tag ? (
              <span class="text-quiz-accent-strong font-medium">{tag}</span>
            ) : null}
          </li>
        ))}
      </ul>
    ) : null
  }

  {
    readingLines.length > 0 ? (
      <p class="text-quiz-ink-secondary mt-4 text-base/relaxed">
        {readingLines.join(' ')}
      </p>
    ) : null
  }
</figure>

