/** Every set that reaches the noMove block: is what it says true of them? */
import { readFileSync } from 'node:fs';
import { parse } from 'yaml';
import { computeMapMove } from '../src/lib/quiz-engine/map-move';

const raw = readFileSync('src/content/quizzes/scrum-master-ai/index.mdx', 'utf8');
const quiz: any = parse(raw.split('---')[1]);
const scored = quiz.questions.filter((q: any) => q.kind !== 'profile');

let total = 0, noMove = 0, allMiddle = 0, hasContext = 0, neither = 0;
function walk(i: number, resp: Record<string, number>) {
  if (i === scored.length) {
    total++;
    const r = computeMapMove(quiz, resp);
    const halves = [r.reclaim?.sentence, r.redirect?.sentence].filter(Boolean).length;
    if (halves > 0) return;
    if (r.wellPositioned && quiz.mapMove?.wellPositioned) return;
    noMove++;
    const buckets = scored.map((q: any) => q.options[resp[q.id]]?.bucket);
    const middle = buckets.every((b: string) => b === 'mixed');
    const ctx = buckets.some((b: string) => b === 'context');
    if (middle) allMiddle++;
    else if (ctx) hasContext++;
    else neither++;
  } else {
    for (let o = 0; o < scored[i].options.length; o++) walk(i + 1, { ...resp, [scored[i].id]: o });
  }
}
walk(0, {});

console.log(`sets reaching the noMove block: ${noMove} of ${total.toLocaleString()}`);
console.log(`  every answer in the middle          ${allMiddle}`);
console.log(`  had a constraint outside their control ${hasContext}`);
console.log(`  neither (copy would still be wrong)  ${neither}`);
console.log(`\ncopy now reads:\n  ${quiz.mapMove.noMove.trim()}`);
EOF
npx tsx temp/check-nomove.ts
